package in.tucor.api.admin;
import jakarta.persistence.*;
import java.time.Instant;
import java.util.UUID;
@Entity @Table(name="admin_settings") public class AdminSetting {@Id @Column(name="user_id") public UUID userId;@Column(name="platform_name",nullable=false) public String platformName="TUCOR";@Column(name="support_email",nullable=false) public String supportEmail="support@tucor.in";@Column(name="platform_fee_percent",nullable=false) public String platformFeePercent="5";@Column(name="min_order_liters",nullable=false) public String minOrderLiters="50";@Column(name="verification_days",nullable=false) public String verificationDays="3";@Column(name="auto_approve_threshold",nullable=false) public String autoApproveThreshold="500";@Column(name="email_new_registrations",nullable=false) public boolean emailNewRegistrations=true;@Column(name="email_disputes",nullable=false) public boolean emailDisputes=true;@Column(name="email_payment_failures",nullable=false) public boolean emailPaymentFailures=true;@Column(name="sms_urgent_alerts",nullable=false) public boolean smsUrgentAlerts=true;@Column(name="daily_digest",nullable=false) public boolean dailyDigest=false;@Column(name="updated_at",nullable=false) public Instant updatedAt;@PrePersist @PreUpdate void touch(){updatedAt=Instant.now();}}
